"""Small original starter bank for offline practice.

These are newly written syllabus-aligned examples, not Kerala PSC past-paper
reproductions. Current-affairs items are intentionally supplied by the learner
so dated facts are not presented as current.
"""


def q(qid, domain, topic, question, answer, distractors, explanation, difficulty=4, source_hint="", mnemonic=""):
    options = [answer, *distractors]
    if len(options) != 4 or len(set(options)) != 4:
        raise ValueError(f"Question {qid} must have four unique choices")
    return {
        "id": qid,
        "domain": domain,
        "topic": topic,
        "question": question,
        "options": {letter: option for letter, option in zip("ABCD", options)},
        "answer": "A",
        "explanation": explanation,
        "mnemonic": mnemonic,
        "difficulty": difficulty,
        "source_hint": source_hint,
    }


